package com.signalchain.app.agent
import com.signalchain.app.dsp.*;import kotlin.math.*
data class AnalysisResult(val snrDb:Double,val noiseStationarityCv:Double,val stationaryNoise:Boolean,val speechActivityRatio:Double)
object AudioAnalyzer{fun analyze(x:FloatArray,fs:Int):AnalysisResult{val fp=FrameParams.create(x.size,fs);val v=Vad.detect(PreEmphasis.apply(x),fp);val noise=v.frameEnergy.filterIndexed{i,_->!v.isSpeech[i]};val mean=noise.average();val cv=sqrt(noise.map{(it-mean)*(it-mean)}.average())/(mean+1e-12);val e=FloatArray(fp.numFrames){i->val st=i*fp.hopLen;val n=min(fp.frameLen,x.size-st);if(n<=0)0f else (0 until n).sumOf{x[st+it].toDouble()*x[st+it]}.toFloat()/fp.frameLen};val se=e.sorted();val nf=max(2,(.15*e.size).toInt());val snr=(10*log10(max(e.average()-se.take(nf).average(),1e-10)/max(se.take(nf).average(),1e-10))).coerceIn(-20.0,40.0);return AnalysisResult(round(snr*100)/100.0,round(cv*10000)/10000.0,cv<.55,v.isSpeech.count{it}.toDouble()/fp.numFrames)}}}
